import vuedraggable from 'vuedraggable'
export default {
    name: 'c_hot_word',
    props: {
        name: {
            type: String
        },
        configData:{
            type:null
        }
    },
    components: {
        draggable: vuedraggable
    },
    data () {
        return {
            hotWordList: [],
            hotIndex: 1,
            defaults: {},
            datas: this.configData
        }
    },
    mounted () {},
    watch: {
        configData: {
            handler (nVal, oVal) {
                this.datas = nVal
            },
            deep: true
        }
    },
    methods: {
        addHotTxt () {
            let obj = {}
            if(this.datas[this.name].list.length>0){
                obj= JSON.parse(JSON.stringify(this.datas.hotList.list[this.datas.hotList.list.length - 1]))
            }else{
                obj= {
                    val:''
                }
            }

            this.datas[this.name].list.push(obj)
        },
        close(index){
            this.datas[this.name].list.splice(index,1)
        }
    }
}
